// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(address actor, uint256 ts, uint256 diff) public {
        vm.assume(actor != address(c) && actor != address(this) && actor.code.length == 0);
        vm.warp(bound(ts, 0, type(uint64).max));
        vm.roll(bound(diff, 0, type(uint64).max));
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
        vm.assume(random == 1); // losing draw: no payout branch taken
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        assertTrue(c.pot() == 10);
    }
}
